	DECKS: "decks",
	CARD_REVIEWS: "card-reviews",
	QUESTION_CHECKS: "question-checks",
} as const;

export interface KeatingStoragePortableData {
	lessonPlans: LessonPlan[];
	lessonMaps: LessonMap[];
	animations: Animation[];
