	goals: LearnerGoal[];
	quizResults: QuizResultRecord[];
	decks: FlashcardDeck[];
	cardReviews: CardReviewRecord[];
	questionChecks: QuestionCheckRecord[];
}

export interface KeatingStorageImportResult {
	lessonPlans: number;
	lessonMaps: number;
	animations: number;
	verifications: number;
	benchmarks: number;
	evolutions: number;
	policies: number;
	feedback: number;
	promptEvolutions: number;
	improvements: number;
