	reset: () => void;
	subscribe: (listener: (context: string) => void) => () => void;
}

const browserLearnerProfileStore: LearnerProfileStore = {
	load: loadLearnerContext,
	save: saveLearnerContext,
	reset: resetLearnerContext,
