function defaultNow(): number {
	return typeof performance !== "undefined" ? performance.now() : Date.now();
}

function defaultId(): string {
	if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
		return crypto.randomUUID();
	}
	return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
}

function safeValue<T>(read: () => T, fallback: T): T {
	try {
		return read();
	} catch {
		return fallback;
	}
}

function finite(value: unknown): value is number {
	return typeof value === "number" && Number.isFinite(value);
}

function elapsed(startedAt: number, endedAt: number): number {
	return Math.max(0, endedAt - startedAt);
}

function isAssistantMessage(message: AgentMessage): message is AssistantMessage {
	return Boolean(message && typeof message === "object" && message.role === "assistant");
}

function modelFrom(value: Model<string> | AgentAnalyticsModel | null | undefined): AgentAnalyticsModel {
	if (!value || typeof value !== "object") return { id: "unknown", provider: "unknown" };
	return {
		id: typeof value.id === "string" && value.id ? value.id : "unknown",
		provider:
			typeof value.provider === "string" && value.provider
				? value.provider
				: "unknown",
	};
}

function modelFromMessage(
	message: AssistantMessage,
	fallback: AgentAnalyticsModel,
): AgentAnalyticsModel {
	return {
		id: message.responseModel || message.model || fallback.id,
		provider: message.provider || fallback.provider,
	};
}

function countUserMessages(messages: readonly AgentMessage[]): number {
	return messages.reduce((count, message) => count + (message.role === "user" ? 1 : 0), 0);
}

function isTokenDelta(event: AgentEvent & { type: "message_update" }): boolean {
	const update = event.assistantMessageEvent;
	return (
		(update.type === "text_delta" ||
			update.type === "thinking_delta" ||
			update.type === "toolcall_delta") &&
		update.delta.length > 0
	);
}

function usageProperties(usage: Usage | undefined): AgentAnalyticsProperties {
	if (!usage) return {};
	const properties: AgentAnalyticsProperties = {};
	if (finite(usage.input)) properties.$ai_input_tokens = usage.input;
	if (finite(usage.output)) properties.$ai_output_tokens = usage.output;
	if (finite(usage.totalTokens)) properties.$ai_total_tokens = usage.totalTokens;
	if (finite(usage.cacheRead)) {
		properties.$ai_cache_read_input_tokens = usage.cacheRead;
	}
	if (finite(usage.cacheWrite)) {
		properties.$ai_cache_creation_input_tokens = usage.cacheWrite;
	}
	if (finite(usage.cacheWrite1h)) {
		properties.$ai_cache_creation_1h_input_tokens = usage.cacheWrite1h;
	}
	if (usage.cost) {
		if (finite(usage.cost.input)) properties.$ai_input_cost_usd = usage.cost.input;
		if (finite(usage.cost.output)) properties.$ai_output_cost_usd = usage.cost.output;
		if (finite(usage.cost.cacheRead)) {
			properties.$ai_cache_read_cost_usd = usage.cost.cacheRead;
		}
		if (finite(usage.cost.cacheWrite)) {
			properties.$ai_cache_write_cost_usd = usage.cost.cacheWrite;
		}
		if (finite(usage.cost.total)) properties.$ai_total_cost_usd = usage.cost.total;
	}
	return properties;
}

function boundedText(value: string): string {
	return value.slice(0, 16_000);
}

function completedEnvelope(
	run: RunTelemetry,
	endedAt: number,
	content: { input: string; output: string } | undefined,
): AgentTraceEnvelopeV1 {
	const generations = run.completedGenerations.slice(0, 32);
	const tools = run.completedTools.slice(0, 32);
	return {
		schema_version: AGENT_TRACE_ENVELOPE_VERSION,
		run_id: run.runId,
		session_id: run.sessionId,
		turn_index: run.turnIndex,
		provider: run.model.provider,
		model: run.model.id,
		source: run.source,
		status: run.status,
		...(run.errorCategory ? { error_category: run.errorCategory } : {}),
		duration_ms: elapsed(run.startedAt, endedAt),
		generation_count: generations.length,
		tool_count: tools.length,
		app_version: run.appVersion,
		surface: "web",
		generations,
		tools,
		...(content ? { evaluation_content: { input: boundedText(content.input), output: boundedText(content.output) } } : {}),
	};
}

/**
 * Subscribe PostHog-compatible behavioral and LLM telemetry to a Pi Agent.
 *
 * This boundary deliberately accepts only behavioral identifiers and numeric
 * usage data. Prompt/response content, tool arguments/results, and raw errors
 * are never added to a capture payload.
 */
export function subscribeAgentAnalytics(
	agent: Agent | AgentAnalyticsAgent,
	options: AgentAnalyticsOptions,
): () => void {
	const now = options.now ?? defaultNow;
	const createId = options.createId ?? defaultId;
	let activeRun: RunTelemetry | undefined;
	let disposed = false;

	const capture = (event: string, properties: AgentAnalyticsProperties): void => {
		if (disposed) return;
		try {
			options.capture(event, properties);
		} catch {
			// Analytics must never interrupt an agent run.
		}
	};

	const readSessionId = (): string =>
		typeof options.sessionId === "function"
			? safeValue(options.sessionId, "unknown")
			: options.sessionId;

	const readModel = (): AgentAnalyticsModel =>
		modelFrom(
			options.getModel
				? safeValue(options.getModel, null)
				: safeValue(() => agent.state.model, null),
		);

	const readSource = (): string => {
		const value = options.getSource
			? safeValue(options.getSource, null)
			: undefined;
		return typeof value === "string" && value ? value : "unknown";
	};

	const readTurnIndex = (): number => {
		const value = options.getTurnIndex
			? safeValue(options.getTurnIndex, 0)
			: safeValue(() => countUserMessages(agent.state.messages), 0);
		return finite(value) ? Math.max(0, Math.floor(value)) : 0;
	};

import type { CaptureResult, Properties } from "posthog-js";

/**
 * Custom properties that can contain learner-authored or model-authored data.
 * Keating analytics are deliberately behavioral: content stays on the user's
 * device and with the model provider they selected.
 */
const PRIVATE_CONTENT_PROPERTIES = new Set([
	"args",
	"content",
	"error",
	"error_message",
	"input",
	"message",
	"messages",
	"output",
	"prompt_text",
	"response",
	"result",
	"sample_text",
	"tool_args",
	"tool_result",
	"topic",
	"$ai_input",
	"$ai_output_choices",
	"$el_text",
	"$exception_message",
]);

const PRIVATE_ROUTE_PATTERNS: ReadonlyArray<[RegExp, string]> = [
	[/^\/s\/[^/]+/, "/s/:shareId"],
	[/^\/courses\/join\/[^/]+/, "/courses/join/:token"],
	[/^\/courses\/[^/]+/, "/courses/:courseId"],
	[/^\/usage\/evolution\/[^/]+/, "/usage/evolution/:evolutionId"],
];

export function analyticsPath(pathname: string): string {
	for (const [pattern, replacement] of PRIVATE_ROUTE_PATTERNS) {
		if (pattern.test(pathname)) return pathname.replace(pattern, replacement);
	}
	return pathname;
}

/** Remove query strings, hashes, share IDs, invite tokens, and course IDs. */
export function analyticsUrl(value: unknown): unknown {
	if (typeof value !== "string" || !value) return value;
	try {
		const url = new URL(value, "https://keating.invalid");
		url.pathname = analyticsPath(url.pathname);
		url.search = "";
		url.hash = "";
		return url.origin === "https://keating.invalid" ? url.pathname : url.toString();
	} catch {
		return value.split(/[?#]/, 1)[0];
	}
}

export function sanitizeAnalyticsProperties(properties: Properties): Properties {
	const sanitized: Properties = { ...properties };
	for (const key of PRIVATE_CONTENT_PROPERTIES) delete sanitized[key];
	if (Array.isArray(sanitized.$exception_list)) {
		sanitized.$exception_list = sanitized.$exception_list.map((exception: unknown) => {
			if (!exception || typeof exception !== "object") return exception;
			const item = exception as Record<string, unknown>;
			return {
				...item,
				value: typeof item.type === "string" ? `[${item.type}]` : "[redacted]",
			};
		});
	}

	for (const key of ["$current_url", "$referrer", "$pathname", "$prev_pageview_pathname"]) {
		if (key in sanitized) sanitized[key] = analyticsUrl(sanitized[key]);
	}

	return sanitized;
}

export function sanitizePostHogEvent(event: CaptureResult | null): CaptureResult | null {
	if (!event) return null;
	return {
		...event,
		properties: sanitizeAnalyticsProperties(event.properties ?? {}),
	};
}

export function sanitizeReplayRequest<T extends { name?: string }>(request: T): T {
	const sanitized = {
		...request,
		...(request.name ? { name: String(analyticsUrl(request.name)) } : {}),
	} as T & Record<string, unknown>;
	delete sanitized.requestHeaders;
	delete sanitized.responseHeaders;
	delete sanitized.requestBody;
	delete sanitized.responseBody;
	return sanitized;
}
export const ANALYTICS_PREFERENCES_KEY = "keating.analytics.preferences.v1";

export interface AnalyticsPreferences {
	captureEnabled: boolean;
	replayEnabled: boolean;
	arizeEvaluationEnabled: boolean;
}

export function defaultAnalyticsPreferences(replayAvailable: boolean): AnalyticsPreferences {
	return {
		captureEnabled: true,
		replayEnabled: replayAvailable,
		arizeEvaluationEnabled: false,
	};
}

export function parseAnalyticsPreferences(
	value: string | null,
	replayAvailable: boolean,
): AnalyticsPreferences {
	const fallback = defaultAnalyticsPreferences(replayAvailable);
	if (!value) return fallback;

	try {
		const parsed = JSON.parse(value) as Partial<AnalyticsPreferences>;
		return {
			captureEnabled:
				typeof parsed.captureEnabled === "boolean"
					? parsed.captureEnabled
					: fallback.captureEnabled,
			replayEnabled:
				replayAvailable &&
				(typeof parsed.replayEnabled === "boolean"
					? parsed.replayEnabled
					: fallback.replayEnabled),
			arizeEvaluationEnabled:
				typeof parsed.arizeEvaluationEnabled === "boolean"
					? parsed.arizeEvaluationEnabled
					: false,
		};
	} catch {
		return fallback;
	}
}

export function readAnalyticsPreferences(replayAvailable: boolean): AnalyticsPreferences {
	if (typeof window === "undefined") return defaultAnalyticsPreferences(replayAvailable);
	return parseAnalyticsPreferences(
		window.localStorage.getItem(ANALYTICS_PREFERENCES_KEY),
		replayAvailable,
	);
}

export function writeAnalyticsPreferences(preferences: AnalyticsPreferences): void {
	if (typeof window === "undefined") return;
	window.localStorage.setItem(ANALYTICS_PREFERENCES_KEY, JSON.stringify(preferences));
}
