  58	function compareUrgency(left: ComingUpItem, right: ComingUpItem): number {
  59		if (left.overdueCount !== right.overdueCount) return right.overdueCount - left.overdueCount;
  60		if (left.dueCount !== right.dueCount) return right.dueCount - left.dueCount;
  61		const leftDue = left.nextDueAt ?? Number.POSITIVE_INFINITY;
  62		const rightDue = right.nextDueAt ?? Number.POSITIVE_INFINITY;
  63		if (leftDue !== rightDue) return leftDue - rightDue;
  64		return left.title.localeCompare(right.title);
  65	}
