  67	export function buildComingUpQueue({ decks, verifications, learnerState, now = Date.now() }: ComingUpSources): ComingUpQueue {
  68		const priorities = new Map(learnerState.studyPriorities.map((record) => [
  69			`${record.targetType}:${record.targetId}`,
  70			record,
  71		]));
  72		const topicProfiles = new Map(learnerState.topicProfiles.map((profile) => [profile.topic, profile]));
  73		const items: ComingUpItem[] = [];
  74	
  75		for (const deck of decks) {
  76			const dueCards = deck.cards.filter((card) => card.srs.dueAt <= now);
  77			const overdueCards = dueCards.filter((card) => card.srs.dueAt < now - MS_PER_DAY);
  78			const nextDueAt = deck.cards.length > 0
  79				? Math.min(...deck.cards.map((card) => card.srs.dueAt))
  80				: null;
  81			const profile = topicProfiles.get(deck.topic);
  82			items.push({
  83				id: `deck:${deck.id}`,
  84				targetId: deck.id,
  85				targetType: "deck",
  86				...priorityFor("deck", deck.id, dueCards.length > 0 ? "focus" : "maintain", priorities),
  87				title: deck.title,
  88				topic: deck.topic,
  89				description: deck.description?.trim() || "Spaced-repetition deck",
  90				dueCount: dueCards.length,
  91				overdueCount: overdueCards.length,
  92				nextDueAt,
  93				estimatedMinutes: Math.max(1, Math.ceil(dueCards.length * 1.25)),
  94				weakConcepts: profile?.reportedChallenges ?? [],
  95				cardCount: deck.cards.length,
  96				createdAt: deck.createdAt,
  97			});
  98		}
  99	
 100		for (const verification of verifications.filter((item) => !item.completed)) {
 101			const ageDays = Math.max(0, (now - verification.createdAt) / MS_PER_DAY);
 102			items.push({
 103				id: `verification:${verification.id}`,
 104				targetId: verification.id,
 105				targetType: "verification",
 106				...priorityFor("verification", verification.id, ageDays >= 7 ? "focus" : "maintain", priorities),
 107				title: `${verification.topic} check`,
 108				topic: verification.topic,
 109				description: verification.checklist.trim().split("\n").find(Boolean)?.replace(/^[-*\d.)\s]+/, "") || "Open knowledge check",
 110				dueCount: 0,
 111				overdueCount: 0,
 112				nextDueAt: null,
 113				estimatedMinutes: 5,
 114				weakConcepts: topicProfiles.get(verification.topic)?.reportedChallenges ?? [],
 115				cardCount: 0,
 116				createdAt: verification.createdAt,
 117			});
 118		}
 119	
 120		for (const profile of learnerState.topicProfiles.filter((item) => item.status === "needs-review")) {
 121			const hasTopicWork = items.some((item) => item.topic === profile.topic);
 122			if (hasTopicWork) continue;
 123			items.push({
 124				id: `topic:${profile.topic}`,
 125				targetId: profile.topic,
 126				targetType: "topic",
 127				...priorityFor("topic", profile.topic, "focus", priorities),
 128				title: profile.topic,
 129				topic: profile.topic,
 130				description: "Needs a fresh retrieval check",
 131				dueCount: 0,
 132				overdueCount: 0,
 133				nextDueAt: null,
 134				estimatedMinutes: 8,
 135				weakConcepts: profile.reportedChallenges,
 136				cardCount: 0,
 137				createdAt: profile.lastEvidenceAt,
 138			});
 139		}
 140	
 141		const sorted = [...items].sort(compareUrgency);
 142		const lanes: ComingUpQueue["lanes"] = { focus: [], maintain: [], low: [] };
 143		for (const item of sorted) lanes[item.priority].push(item);
 144		const dueDeckIds = sorted
 145			.filter((item) => item.targetType === "deck" && item.dueCount > 0)
 146			.sort((left, right) => {
 147				const priorityRank: Record<StudyPriority, number> = { focus: 0, maintain: 1, low: 2 };
 148				return priorityRank[left.priority] - priorityRank[right.priority] || compareUrgency(left, right);
 149			})
 150			.map((item) => item.targetId);
 151	
 152		return {
 153			items: sorted,
 154			lanes,
 155			dueCardCount: sorted.reduce((sum, item) => sum + item.dueCount, 0),
 156			overdueCardCount: sorted.reduce((sum, item) => sum + item.overdueCount, 0),
 157			estimatedMinutes: sorted.reduce((sum, item) => sum + (item.dueCount > 0 ? item.estimatedMinutes : 0), 0),
 158			dueDeckIds,
 159		};
 160	}

