import type { AsyncSqlDatabase, AsyncSqliteDriver } from "./database";
import { MigrationJournal, type MigrationClock } from "./migration-journal";
import {
  initializeRepositorySchema,
  LEARNER_REPOSITORY_DATABASE_NAME,
} from "./schema";

export * from "./database";
export * from "./migration-journal";
export * from "./schema";

export interface LearnerRepository {
  readonly database: AsyncSqlDatabase;
  readonly migrations: MigrationJournal;
  close(): Promise<void>;
}

export interface OpenLearnerRepositoryOptions {
  clock?: MigrationClock;
  databaseName?: string;
}

/** Opens, configures, and initializes the local repository, closing on failure. */
export async function openLearnerRepository(
  driver: AsyncSqliteDriver,
  options: OpenLearnerRepositoryOptions = {},
): Promise<LearnerRepository> {
  const database = await driver.openDatabaseAsync(
    options.databaseName ?? LEARNER_REPOSITORY_DATABASE_NAME,
  );
  try {
    await initializeRepositorySchema(database);
    let closePromise: Promise<void> | null = null;
    return {
      database,
      migrations: new MigrationJournal(database, options.clock),
      close: () => {
        if (!closePromise) closePromise = database.closeAsync();
        return closePromise;
      },
    };
  } catch (error) {
    await database.closeAsync().catch(() => undefined);
    throw error;
  }
}
import { useEffect, useState } from "react";
import { ActivityIndicator, StyleSheet, Text, View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { colors, spacing, type } from "@/constants/theme";
import { openExpoLearnerRepository } from "@/lib/learner-repository/expo";
import {
  MIGRATION_PHASES,
  type MigrationPhase,
} from "@/lib/learner-repository/migration-journal";

const DATABASE_NAME = "keating-learner-native-smoke.sqlite";
const MIGRATION_ID = "native-expo-sqlite-smoke-v1";
const DIGEST = "a".repeat(64);

async function exerciseNativeRepository(): Promise<void> {
  const repository = await openExpoLearnerRepository({ databaseName: DATABASE_NAME });
  try {
    let entry = await repository.migrations.start({
      id: MIGRATION_ID,
      sourceVersion: 1,
      targetVersion: 1,
      digest: DIGEST,
    });
    const remaining = MIGRATION_PHASES.slice(MIGRATION_PHASES.indexOf(entry.phase) + 1);
    for (const phase of remaining) {
      entry = await repository.migrations.advance(MIGRATION_ID, phase as MigrationPhase);
    }
    if (entry.phase !== "completed") throw new Error("Migration did not complete.");
  } finally {
    await repository.close();
  }

  const reopened = await openExpoLearnerRepository({ databaseName: DATABASE_NAME });
  try {
    const persisted = await reopened.migrations.get(MIGRATION_ID);
    if (persisted?.phase !== "completed" || persisted.digest !== DIGEST) {
      throw new Error("Completed migration did not survive repository restart.");
    }
  } finally {
    await reopened.close();
  }
}

